var userConnection = this.Get<UserConnection>("UserConnection");

var acc = Get<Guid>("BPAccount");
var owner = Get<Guid>("BPOwner");

var projectId = Get<Guid>("BPProjectId");
var taskNumber = Get<String>("BPTaskNumber");
var taskName = Get<String>("BPTaskName");

var MessageBody = JsonConvert.SerializeObject(new { AccId = acc.ToString(),
													OwnId = owner.ToString(),
													TaskNumber = taskNumber,
													TaskName = taskName,
													ProjectId = projectId});

BPMSoft.Configuration.MsgChannelUtilities.PostMessage(userConnection, "TaskClosedInfo", MessageBody);

return true;
